// SendPushNotificationRequest sends a push notification. The request is
// queued and sent to the provider by Centrifugo workers.
// Centrifugo PRO only.
type SendPushNotificationRequest struct {
	// Recipient is who receives the notification. Required.
	Recipient PushRecipient `json:"recipient,omitzero"`

	// Notification is the notification to send. Required.
	Notification PushNotification `json:"notification,omitzero"`

	// UID is a unique identifier of the request, can be used to cancel the
	// push. UUID v4 is recommended; different requests must use different
	// uids.
	UID string `json:"uid,omitzero"`

	// SendAt is the Unix time in seconds when to send the notification. If
	// not set, the notification is sent immediately.
	SendAt int64 `json:"send_at,omitzero"`

	// OptimizeForReliability makes processing heavier, but tolerates edge
	// cases, like not losing inflight pushes when the queue is briefly
	// unavailable.
	OptimizeForReliability bool `json:"optimize_for_reliability,omitzero"`

	// LimitStrategy sets time constraints and rate limits. Only applies
	// with a filter recipient; devices are then processed one by one
	// instead of in batches.
	LimitStrategy PushLimitStrategy `json:"limit_strategy,omitzero"`

	// AnalyticsUID is the identifier for push notification analytics. If
	// not set, uid is used.
	AnalyticsUID string `json:"analytics_uid,omitzero"`

	// Localizations are optional per language/locale localizations. Setting
	// them enables templating.
	Localizations map[string]PushLocalization `json:"localizations,omitzero"`

	// UseTemplating enables templating of the notification. Only works
	// with a filter recipient.
	UseTemplating bool `json:"use_templating,omitzero"`

	// UseMeta additionally loads device meta while sending, making it
	// available in templating.
	UseMeta bool `json:"use_meta,omitzero"`
}

